<!DOCTYPE html>
<html lang="ja">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <meta name="csrf-token" content="{{ csrf_token() }}">
  <title>Foodiex 管理パネル</title>
  <script src="/vendors/admin/tailwindcss.js?v=20261119"></script>
  <script src="/vendors/admin/react.production.min.js?v=20261119"></script>
  <script src="/vendors/admin/react-dom.production.min.js?v=20261119"></script>
  <script src="/vendors/admin/htm.umd.js?v=20261119"></script>
  <style>
    :root{font-family:'Plus Jakarta Sans','Noto Sans JP',sans-serif} body{margin:0;background:#F7F8FA;color:#111827}.card{background:#fff;border-radius:16px;box-shadow:0 2px 12px rgba(17,24,39,.05)}.fade{animation:f .25s ease}@keyframes f{from{opacity:0;transform:translateY(6px)}to{opacity:1}}
  </style>
</head>
<body><div id="root"></div>
<script>
@verbatim
const {useState,useEffect,useMemo}=React,h=htm.bind(React.createElement);
const O='#F46A25', G='#10B981', Y='#F59E0B', R='#EF4444';
const NAV=[['概要','▦','Overview'],['注文','🧾','Orders'],['配達','🚚','Delivery'],['レストラン','🏪','Restaurants'],['ドライバー','🛵','Drivers'],['顧客','👥','Customers'],['商品','🍔','Products'],['財務','💳','Financials'],['プロモ・割引','🏷️','Promo'],['クレーム','💬','Complaints'],['レポート','📊','Reports'],['設定','⚙️','Settings']];
const DRIVERS=[{id:1,name:'Omar Khaled',vehicle:'Motorbike',rating:4.9,deliveries:1240,balance:320,online:true},{id:2,name:'Youssef Adel',vehicle:'Bicycle',rating:4.7,deliveries:860,balance:150,online:true},{id:3,name:'Karim Samy',vehicle:'Motorbike',rating:4.8,deliveries:1022,balance:0,online:false},{id:4,name:'Mostafa Nabil',vehicle:'Car',rating:4.5,deliveries:540,balance:780,online:true},{id:5,name:'Hassan Ali',vehicle:'Motorbike',rating:4.6,deliveries:712,balance:95,online:false}];
const statusClass=s=>({Paid:'bg-emerald-100 text-emerald-700',Pending:'bg-gray-100 text-gray-600','COD Unsettled':'bg-amber-100 text-amber-700',Failed:'bg-red-100 text-red-600',Refunded:'bg-purple-100 text-purple-700'}[s]||'bg-gray-100 text-gray-600');

async function api(path,options={}){const r=await fetch(path,{credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]')?.content||'',...(options.headers||{})},...options});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||d.errors?.email?.[0]||'Request failed');return d}

function Modal({title,onClose,children}){return h`<div className="fixed inset-0 z-50 bg-black/40 flex items-center justify-center p-4" onClick=${onClose}><div className="card w-full max-w-md p-6 fade" onClick=${e=>e.stopPropagation()}><div className="flex justify-between items-center mb-4"><h3 className="text-lg font-bold">${title}</h3><button onClick=${onClose} className="text-gray-400">✕</button></div>${children}</div></div>`}
function Badge({text}){return h`<span className=${'px-2.5 py-1 rounded-full text-xs font-semibold '+statusClass(text)}>${text}</span>`}
function Btn({children,onClick,danger=false,className=''}){return h`<button onClick=${onClick} className=${'px-4 py-2 rounded-full text-sm font-semibold transition hover:opacity-90 '+(danger?'bg-red-500 text-white':'bg-[#F46A25] text-white')+' '+className}>${children}</button>`}
function Table({heads,rows}){return h`<div className="overflow-x-auto"><table className="w-full text-sm text-left"><thead><tr className="text-gray-400 text-xs uppercase">${heads.map(x=>h`<th key=${x} className="py-3 pr-4 font-medium">${x}</th>`)}</tr></thead><tbody>${rows.map((r,i)=>h`<tr key=${i} className="border-t border-gray-100 hover:bg-orange-50/40">${r.map((c,j)=>h`<td key=${j} className="py-3 pr-4 whitespace-nowrap">${c}</td>`)}</tr>`)}</tbody></table></div>`}

function Login({onLogin,demo}){const [mode,setMode]=useState('login'),[name,setName]=useState(''),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[confirm,setConfirm]=useState(''),[adminKey,setAdminKey]=useState(''),[show,setShow]=useState(false),[remember,setRemember]=useState(true),[error,setError]=useState(''),[loading,setLoading]=useState(false);const submit=async(e)=>{e.preventDefault();setError('');if(mode==='register'&&password!==confirm){setError('パスワードが一致しません。');return}setLoading(true);try{await fetch('/sanctum/csrf-cookie',{credentials:'same-origin'});const d=await api(mode==='register'?'/api/admin/register':'/api/admin/login',{method:'POST',body:JSON.stringify(mode==='register'?{name,email,password,password_confirmation:confirm,admin_key:adminKey}:{email,password,remember})});onLogin(d.user)}catch(x){setError(x.message)}finally{setLoading(false)}};return h`<div className="min-h-screen grid place-items-center p-4"><div className="card w-full max-w-md p-8 fade"><div className="text-2xl font-extrabold mb-1 text-[#F46A25]">🚚 Foodiex</div><h1 className="text-xl font-bold mb-1">${mode==='login'?'管理者ログイン':'新規アカウント作成'}</h1><p className="text-sm text-gray-500 mb-6">${mode==='login'?'Admin sign in':'Create Admin Account'}</p>${error&&h`<div className="mb-4 rounded-xl bg-red-50 text-red-600 text-sm px-4 py-3">${error}</div>`}<form onSubmit=${submit}>${mode==='register'&&h`<><label className="block text-sm font-semibold mb-2">名前 / Name</label><input required value=${name} onChange=${e=>setName(e.target.value)} className="w-full border border-gray-200 rounded-xl px-4 py-3 mb-4"/>`}${h`<label className="block text-sm font-semibold mb-2">Email</label><input type="email" required value=${email} onChange=${e=>setEmail(e.target.value)} className="w-full border border-gray-200 rounded-xl px-4 py-3 mb-4"/>`}<label className="block text-sm font-semibold mb-2">Password</label><div className="relative mb-4"><input type=${show?'text':'password'} required value=${password} onChange=${e=>setPassword(e.target.value)} className="w-full border border-gray-200 rounded-xl px-4 py-3 pr-20"/><button type="button" onClick=${()=>setShow(!show)} className="absolute right-3 top-3 text-xs text-gray-500">${show?'Hide':'Show'}</button></div>${mode==='register'&&h`<><label className="block text-sm font-semibold mb-2">Confirm Password</label><input type=${show?'text':'password'} required value=${confirm} onChange=${e=>setConfirm(e.target.value)} className="w-full border border-gray-200 rounded-xl px-4 py-3 mb-4"/><label className="block text-sm font-semibold mb-2">Admin Invite / Setup Key</label><input type="password" required value=${adminKey} onChange=${e=>setAdminKey(e.target.value)} className="w-full border border-gray-200 rounded-xl px-4 py-3 mb-4"/></>`}${mode==='login'&&h`<label className="flex items-center gap-2 text-sm text-gray-600 mb-5"><input type="checkbox" checked=${remember} onChange=${e=>setRemember(e.target.checked)}/>Remember me</label>`}<button disabled=${loading} className="w-full rounded-full bg-[#F46A25] text-white py-3 font-semibold">${mode==='login'?'ログイン':'新規登録'}</button></form><button type="button" onClick=${()=>{setMode(mode==='login'?'register':'login');setError('')}} className="w-full mt-4 text-sm text-[#F46A25] font-semibold">${mode==='login'?"Don't have an account? Create Admin Account / 新規登録":"アカウントがありますか？ ログイン"}</button></div></div>`}

function Overview({orders,stats}){const k=stats?.kpis||{};const data=[['Success orders',k.success_orders||0,G,'✓'],['Delayed orders',k.delayed_orders||0,Y,'⏱'],['Canceled orders',k.canceled_orders||0,R,'✕'],['Total Stripe Revenue',k.total_revenue||0,G,'¥']];return h`<div className="fade"><h2 className="text-2xl font-bold mb-4">注文概要</h2><div className="grid sm:grid-cols-2 xl:grid-cols-4 gap-4">${data.map(([l,n,c,i])=>h`<div key=${l} className="card p-5 flex justify-between"><div><div className="text-xs font-semibold">${l}</div><div className="text-3xl font-extrabold my-1" style=${{color:c}}>${l.includes('Revenue')?'¥'+Number(n).toLocaleString('ja-JP'):n}</div><div className="text-xs text-gray-500">Live database</div></div><div className="w-11 h-11 rounded-full text-white grid place-items-center" style=${{background:c}}>${i}</div></div>`)}</div><div className="card p-6 mt-5"><h3 className="font-bold text-lg mb-4">Live Active Orders</h3><Table heads=${['Order','Customer','Items','Amount','Status']} rows=${orders.slice(0,8).map(o=>[h`<b>${o.id}</b>`,o.customer,o.items?.map(i=>i.name+' ×'+i.quantity).join(', ')||o.restaurant,'¥'+Number(o.amount).toLocaleString('ja-JP'),h`<Badge text=${o.status}/>`])}/></div></div>`}

function Orders({orders,setOrders,toast}){const [filter,setFilter]=useState('All');const [selected,setSelected]=useState(null);const list=orders.filter(o=>filter==='All'||o.status===filter);const update=async(o,status)=>{try{await api('/api/admin/orders/'+encodeURIComponent(o.id.replace('#',''))+'/status',{method:'PATCH',body:JSON.stringify({status})});setOrders(orders.map(x=>x.id===o.id?{...x,status}:x));toast('注文ステータスを更新しました')}catch(e){toast(e.message)}};return h`<div className="fade"><div className="flex gap-2 flex-wrap mb-4">${['All','Pending','Preparing','On the Way','Delivered','Delayed','Canceled'].map(x=>h`<button onClick=${()=>setFilter(x)} key=${x} className=${'px-4 py-2 rounded-full text-sm font-semibold '+(filter===x?'bg-[#F46A25] text-white':'bg-white')}>${x}</button>`)}</div><div className="card p-6"><Table heads=${['Order','Customer','Delivery','Amount','Payment','Status','']} rows=${list.map(o=>[h`<b>${o.id}</b>`,h`<div>${o.customer}<div className="text-xs text-gray-400">${o.phone||''}</div></div>`,o.address||'店頭受取','¥'+Number(o.amount).toLocaleString('ja-JP'),h`<Badge text=${o.paymentStatus}/>`,h`<select value=${o.status} onChange=${e=>update(o,e.target.value)} className="rounded-full px-2 py-1 text-xs font-semibold">${['Pending','Preparing','On the Way','Delivered','Delayed','Canceled'].map(s=>h`<option key=${s}>${s}</option>`)}</select>`,h`<button onClick=${()=>setSelected(o)} className="text-[#F46A25] font-semibold">詳細</button>`])}/></div>${selected&&h`<${Modal} title=${'注文 '+selected.id} onClose=${()=>setSelected(null)}><div className="text-sm space-y-2"><div><b>Customer:</b> ${selected.customer}</div><div><b>Email:</b> ${selected.email||'—'}</div><div><b>Address:</b> ${selected.address||'店頭受取'}</div><div><b>Payment:</b> ${selected.paymentStatus} (${selected.paymentMethod||'stripe'})</div><hr/><b>Items</b>${selected.items?.map(i=>h`<div key=${i.name} className="flex justify-between mt-2"><span>${i.name} × ${i.quantity}</span><span>¥${Number(i.price*i.quantity).toLocaleString('ja-JP')}</span></div>`)||[]}</div></${Modal}>`}</div>`}

function Financials({orders,setOrders,toast}){const [payment,setPayment]=useState(null),[status,setStatus]=useState('Paid'),[reference,setReference]=useState('');const paid=orders.filter(o=>o.paymentStatus==='Paid').reduce((s,o)=>s+Number(o.amount),0),pending=orders.filter(o=>o.paymentStatus==='Pending').reduce((s,o)=>s+Number(o.amount),0),refunded=orders.filter(o=>o.paymentStatus==='Refunded').reduce((s,o)=>s+Number(o.amount),0);const update=async()=>{if(!payment)return;try{await api('/api/admin/payments/'+encodeURIComponent(payment.id.replace('#',''))+'/status',{method:'PATCH',body:JSON.stringify({status,reference})});setOrders(orders.map(o=>o.id===payment.id?{...o,paymentStatus:status}:o));setPayment(null);toast('決済ステータスを更新しました')}catch(e){toast(e.message)}};return h`<div className="fade"><div className="grid sm:grid-cols-3 gap-4 mb-5"><div className="card p-5"><div className="text-xs text-gray-500">Total Stripe Revenue (Paid)</div><div className="text-2xl font-bold text-emerald-600">¥${paid.toLocaleString('ja-JP')}</div></div><div className="card p-5"><div className="text-xs text-gray-500">Pending / Unsettled</div><div className="text-2xl font-bold text-amber-600">¥${pending.toLocaleString('ja-JP')}</div></div><div className="card p-5"><div className="text-xs text-gray-500">Refunded</div><div className="text-2xl font-bold text-purple-600">¥${refunded.toLocaleString('ja-JP')}</div></div></div><div className="card p-6"><h3 className="font-bold mb-4">Stripe Transactions Ledger</h3><Table heads=${['Order ID','Customer','Stripe Payment Intent','Amount Paid','Status','Timestamp','']} rows=${orders.map(o=>[o.id,o.customer,o.stripePaymentIntentId||'—','¥'+Number(o.amount).toLocaleString('ja-JP'),h`<Badge text=${o.paymentStatus}/>`,o.createdAt,h`<button onClick=${()=>{setPayment(o);setStatus(o.paymentStatus||'Pending');setReference(o.stripePaymentIntentId||'')}} className="text-[#F46A25] font-semibold">更新</button>`])}/></div>${payment&&h`<${Modal} title=${'決済ステータス '+payment.id} onClose=${()=>setPayment(null)}><label className="block text-sm font-semibold mb-2">Payment status</label><select value=${status} onChange=${e=>setStatus(e.target.value)} className="w-full border rounded-xl px-3 py-2 mb-3">${['Paid','Pending','Refunded','Failed'].map(s=>h`<option key=${s}>${s}</option>`)}</select><label className="block text-sm font-semibold mb-2">Stripe Payment Intent ID</label><input value=${reference} onChange=${e=>setReference(e.target.value)} className="w-full border rounded-xl px-3 py-2 mb-4"/><${Btn} onClick=${update}>保存</${Btn}></${Modal}>`}</div>`}

function MenuManager({toast}){const [products,setProducts]=useState([]),[modal,setModal]=useState(null),[description,setDescription]=useState(''),[name,setName]=useState(''),[price,setPrice]=useState(''),[category,setCategory]=useState('洋食'),[subcategory,setSubcategory]=useState(''),[stock,setStock]=useState(true),[file,setFile]=useState(null);const load=async()=>{try{const d=await api('/api/admin/menu');setProducts(d.products||[])}catch(e){toast(e.message)}};useEffect(()=>{load()},[]);const openAdd=()=>{setModal('add');setName('');setPrice('');setCategory('洋食');setSubcategory('');setStock(true);setDescription('');setFile(null)};const openEdit=p=>{setModal(p);setName(p.name);setPrice(p.price);setCategory(p.category||'洋食');setSubcategory(p.subcategory||'');setStock(!!p.is_available);setDescription(p.description||'');setFile(null)};const save=async()=>{if(!name.trim()||Number(price)<1)return toast('料理名と価格を入力してください');const form=new FormData();form.set('name',name.trim());form.set('price',String(Number(price)));form.set('category',category);form.set('subcategory',subcategory);form.set('description',description);form.set('is_available',stock?'1':'0');form.set('restaurant','NK-EATS');if(file)form.set('image',file);try{const url=modal==='add'?'/api/admin/products':'/api/admin/products/'+modal.id;const r=await fetch(url,{method:modal==='add'?'POST':'POST',headers:{'Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]')?.content||''},body:form,credentials:'same-origin'});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||'保存に失敗しました');if(modal!=='add')await fetch(url,{method:'PATCH',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]')?.content||''},body:JSON.stringify({name:name.trim(),price:Number(price),category,description,is_available:stock,restaurant:'NK-EATS'}),credentials:'same-origin'});setModal(null);await load();toast(modal==='add'?'料理を追加しました':'料理を更新しました')}catch(e){toast(e.message)}};const toggle=async p=>{try{await api('/api/admin/products/'+p.id+'/toggle',{method:'PATCH',body:JSON.stringify({is_available:!p.is_available})});await load()}catch(e){toast(e.message)}};const remove=async p=>{if(!confirm(p.name+' を削除しますか？'))return;try{await api('/api/admin/products/'+p.id,{method:'DELETE'});await load();toast('料理を削除しました')}catch(e){toast(e.message)}};return h`<div className="fade card p-6"><div className="flex justify-between items-center mb-4"><h3 className="font-bold text-lg">商品 / Menu</h3><${Btn} onClick=${openAdd}>＋ Add New Product</${Btn}></div><Table heads=${['Image','料理','カテゴリー','価格','在庫','']} rows=${products.map(p=>[h`<img src=${p.image_url||''} alt=${p.name} className="w-14 h-14 object-cover rounded-lg"/>`,p.name,p.category||'—','¥'+Number(p.price).toLocaleString('ja-JP'),h`<button onClick=${()=>toggle(p)} className=${'w-11 h-6 rounded-full p-0.5 '+(p.is_available?'bg-emerald-500':'bg-gray-300')}><span className=${'block w-5 h-5 bg-white rounded-full '+(p.is_available?'translate-x-5':'')}></span></button>`,h`<div className="flex gap-3"><button onClick=${()=>openEdit(p)} className="text-blue-600 font-semibold">編集</button><button onClick=${()=>remove(p)} className="text-red-500 font-semibold">削除</button></div>`])}/>${modal&&h`<${Modal} title=${modal==='add'?'+ Add New Product':'商品を編集'} onClose=${()=>setModal(null)}><div className="space-y-3"><input value=${name} onChange=${e=>setName(e.target.value)} className="w-full border rounded-xl px-3 py-2" placeholder="Product Name"/><select value=${category} onChange=${e=>setCategory(e.target.value)} className="w-full border rounded-xl px-3 py-2 mb-4">${['洋食','ネパール料理'].map(c=>h`<option key=${c} value=${c}>${c}</option>`)}</select><input type="number" min="1" value=${price} onChange=${e=>setPrice(e.target.value)} className="w-full border rounded-xl px-3 py-2" placeholder="Price (JPY)"/><textarea value=${description} onChange=${e=>setDescription(e.target.value)} className="w-full border rounded-xl px-3 py-2 h-20" placeholder="Description"/><input type="file" accept="image/*" onChange=${e=>setFile(e.target.files[0]||null)} className="w-full border rounded-xl px-3 py-2"/><label className="flex items-center gap-2"><input type="checkbox" checked=${stock} onChange=${e=>setStock(e.target.checked)}/>Available / In stock</label><${Btn} onClick=${save}>保存</${Btn}></div></${Modal}>`}</div>`}

function Complaints({toast}){const [tickets,setTickets]=useState([{id:'T-201',order:'#FX1045',issue:'Food arrived cold',status:'Open'},{id:'T-202',order:'#FX1043',issue:'Missing item: fries',status:'Open'}]);const [modal,setModal]=useState(null);const [reply,setReply]=useState('');const resolve=async(refund=false)=>{try{await api('/api/admin/complaints/'+modal.id.replace('T-','')+'/resolve',{method:'POST',body:JSON.stringify({reply,refund})});setTickets(tickets.map(t=>t.id===modal.id?{...t,status:'Resolved'}:t));setModal(null);setReply('');toast(refund?'Refund issued':'Reply sent')}catch(e){toast(e.message)}};return h`<div className="fade card p-6"><h3 className="font-bold mb-3">Support tickets</h3><Table heads=${['Ticket','Order','Issue','Status','']} rows=${tickets.map(t=>[t.id,t.order,t.issue,t.status,t.status==='Open'?h`<button onClick=${()=>setModal(t)} className="text-[#F46A25] font-semibold">Resolve</button>`:'—'])}/>${modal&&h`<${Modal} title=${'Resolve '+modal.id} onClose=${()=>setModal(null)}><p className="text-sm mb-3">${modal.issue} (${modal.order})</p><textarea value=${reply} onChange=${e=>setReply(e.target.value)} className="w-full border rounded-xl p-3 h-24 mb-3" placeholder="Quick reply..."/><div className="flex gap-2"><${Btn} onClick=${()=>resolve(false)}>Send reply</${Btn}><${Btn} onClick=${()=>resolve(true)} danger=${true}>Refund order</${Btn}></div></${Modal}>`}</div>`}

function Generic({name,toast}){const tables={Customers:{heads:['Customer','Orders','Spent'],rows:[['Sara Mahmoud',24,'4,310 EGP'],['Ali Hassan',18,'3,020 EGP']]},Drivers:{heads:['Driver','COD Balance','Status'],rows:DRIVERS.map(d=>[d.name,d.balance+' EGP',d.online?'Online':'Offline'])},Delivery:{heads:['Area','Orders','Percentage'],rows:[['Cairo',697,'48%'],['Mansoura',435,'30%'],['Alex',318,'22%']]},Settings:{heads:['Setting','Value'],rows:[['Delivery zones','Cairo, Mansoura, Alex'],['Base delivery fee','25 EGP'],['Platform commission','15%']]},Reports:{heads:['Report','Period'],rows:[['Sales summary','Nov 2026'],['Driver performance','Nov 2026']]},Promo:{heads:['Code','Description','Active'],rows:[['WELCOME20','20% off first order','Yes'],['FREESHIP','Free delivery > 200 EGP','Yes']]}};const d=tables[name]||tables.Customers;return h`<div className="fade card p-6"><h3 className="font-bold text-lg mb-3">${name}</h3><${Table} heads=${d.heads} rows=${d.rows}/></div>`}

function App(){const [authenticated,setAuthenticated]=useState(false),[demo,setDemo]=useState(false),[user,setUser]=useState(null),[view,setView]=useState('Overview'),[orders,setOrders]=useState([]),[stats,setStats]=useState({kpis:{},chart:{series:[]}}),[sidebar,setSidebar]=useState(false),[toastM,setToast]=useState('');const toast=m=>{setToast(m);setTimeout(()=>setToast(''),2400)};useEffect(()=>{api('/api/admin/me').then(d=>{if(d.authenticated){setAuthenticated(true);setUser(d.user);const refresh=()=>{api('/api/admin/dashboard-stats').then(setStats).catch(()=>{});api('/api/admin/orders').then(r=>setOrders(r.orders||[])).catch(()=>{})};refresh();const timer=setInterval(refresh,15000);window.__nkAdminTimer=timer}}).catch(()=>{})},[]);const logout=async()=>{if(!demo)try{await api('/api/admin/logout',{method:'POST',body:'{}'})}catch(e){ }setDemo(false);setAuthenticated(false);setUser(null)};if(!authenticated&&!demo)return h`<${Login} onLogin=${u=>{setUser(u);setAuthenticated(true)}} demo=${()=>setDemo(true)}/>`;const panel=view==='Overview'?h`<${Overview} orders=${orders} stats=${stats}/>`:view==='Orders'?h`<${Orders} orders=${orders} setOrders=${setOrders} toast=${toast}/>`:view==='Financials'?h`<${Financials} orders=${orders} toast=${toast}/>`:view==='Restaurants'?h`<${Vendors} toast=${toast}/>`:view==='Products'?h`<${MenuManager} toast=${toast}/>`:view==='Complaints'?h`<${Complaints} toast=${toast}/>`:h`<${Generic} name=${view} toast=${toast}/>`;
return h`<div className="min-h-screen flex"><button onClick=${()=>setSidebar(true)} className="lg:hidden fixed top-3 left-3 z-30 bg-white rounded-lg px-3 py-2 shadow">☰</button>${sidebar&&h`<div onClick=${()=>setSidebar(false)} className="fixed inset-0 z-30 bg-black/30 lg:hidden"></div>`}<aside className=${'fixed z-40 inset-y-0 left-0 w-60 bg-white flex flex-col transition-transform lg:translate-x-0 '+(sidebar?'':'-translate-x-full')}><div className="px-6 py-6 text-2xl font-extrabold text-[#F46A25]">🚚 Foodiex</div><div className="px-6 text-xs text-gray-400 mb-2">MAIN</div><nav className="flex-1 overflow-y-auto">${NAV.map(([label,icon,key])=>h`<button key=${key} onClick=${()=>{setView(key);setSidebar(false)}} className=${'w-full px-6 py-3 text-left flex gap-3 items-center text-sm '+(view===key?'bg-orange-50 text-[#F46A25] border-r-4 border-[#F46A25]':'text-gray-600')}> <span>${icon}</span><span>${label}</span></button>`)}</nav><button onClick=${logout} className="m-4 px-4 py-3 rounded-xl bg-gray-100 text-sm font-semibold">Logout</button></aside><main className="lg:ml-60 flex-1 p-5 lg:p-8">${panel}</main>${toastM&&h`<div className="fixed bottom-5 right-5 bg-gray-900 text-white px-4 py-3 rounded-xl shadow-lg">${toastM}</div>`}</div>`}
ReactDOM.createRoot(document.getElementById('root')).render(h`<${App}/>`);
@endverbatim
</script></body></html>
